package cmd

import (
	"bufio"
	"fmt"
	"strings"

	"github.com/navidrome/navidrome/conf"
	"github.com/navidrome/navidrome/db"
	"github.com/spf13/cobra"
)

func confirm(cmd *cobra.Command, prompt string) bool {
	_, _ = fmt.Fprintf(cmd.ErrOrStderr(), "%s [y/N]: ", prompt)
	answer, err := bufio.NewReader(cmd.InOrStdin()).ReadString('\n')
	if err != nil && answer == "" {
		return false
	}
	return strings.EqualFold(strings.TrimSpace(answer), "y") || strings.EqualFold(strings.TrimSpace(answer), "yes")
}

func init() {
	backupCmd := &cobra.Command{Use: "backup", Short: "Manage database backups"}
	createCmd := &cobra.Command{
		Use: "create", Short: "Create a database backup", Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			path, err := db.Db().Backup(cmd.Context())
			if err == nil {
				_, _ = fmt.Fprintln(cmd.OutOrStdout(), path)
			}
			return err
		},
	}
	pruneCmd := &cobra.Command{
		Use: "prune", Short: "Remove old database backups", Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			force, _ := cmd.Flags().GetBool("force")
			if conf.Server.Backup.Count == 0 && !force && !confirm(cmd, "Delete all database backups?") {
				return fmt.Errorf("backup pruning cancelled")
			}
			count, err := db.Db().Prune(cmd.Context())
			if err == nil {
				_, _ = fmt.Fprintf(cmd.OutOrStdout(), "Pruned %d backups\n", count)
			}
			return err
		},
	}
	pruneCmd.Flags().BoolP("force", "f", false, "skip confirmation")
	restoreCmd := &cobra.Command{
		Use: "restore", Short: "Restore a database backup", Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			path, _ := cmd.Flags().GetString("backup-file")
			force, _ := cmd.Flags().GetBool("force")
			if !force && !confirm(cmd, "Restore database from "+path+"? This replaces current data") {
				return fmt.Errorf("database restore cancelled")
			}
			if err := db.Db().Restore(cmd.Context(), path); err != nil {
				return err
			}
			_, _ = fmt.Fprintln(cmd.OutOrStdout(), "Database restored")
			return nil
		},
	}
	restoreCmd.Flags().String("backup-file", "", "path to the backup file")
	_ = restoreCmd.MarkFlagRequired("backup-file")
	restoreCmd.Flags().BoolP("force", "f", false, "skip confirmation")
	backupCmd.AddCommand(createCmd, pruneCmd, restoreCmd)
	rootCmd.AddCommand(backupCmd)
}

